package pipeline

import (
	"context"
	"crypto/tls"
	"fmt"
	"log"
	"net/http"
	"regexp"
	"strings"
	"sync"

	"github.com/go-ldap/ldap/v3"
)

// TenantResolver handles multi-tenant LDAP lookups for CI/CD pipeline authorization
type TenantResolver struct {
	mu          sync.RWMutex
	pool        map[string]*ldap.Conn
	baseDN      string
	bindDN      string
	bindPass    string
	ldapHost    string
	filterCache map[string]string
}

var safeIdentifier = regexp.MustCompile(`^[a-zA-Z0-9._-]+$`)

// NewTenantResolver creates a resolver with connection pooling
func NewTenantResolver(host, baseDN, bindDN, bindPass string) *TenantResolver {
	return &TenantResolver{
		pool:        make(map[string]*ldap.Conn),
		baseDN:      baseDN,
		bindDN:      bindDN,
		bindPass:    bindPass,
		ldapHost:    host,
		filterCache: make(map[string]string),
	}
}

// sanitizeComponent removes LDAP special characters from a single component
func sanitizeComponent(input string) string {
	replacer := strings.NewReplacer(
		"\\", "\\5c",
		"*", "\\2a",
		"(", "\\28",
		")", "\\29",
		"\x00", "\\00",
	)
	return replacer.Replace(input)
}

// buildTenantFilter constructs an LDAP filter for tenant pipeline lookup
// Uses a two-phase approach: validate structure, then build filter
func (tr *TenantResolver) buildTenantFilter(tenantID, pipelineGroup string) string {
	tr.mu.RLock()
	cacheKey := tenantID + ":" + pipelineGroup
	if cached, ok := tr.filterCache[cacheKey]; ok {
		tr.mu.RUnlock()
		return cached
	}
	tr.mu.RUnlock()

	// Phase 1: Structural validation of tenant ID
	if !safeIdentifier.MatchString(tenantID) {
		log.Printf("rejected invalid tenant ID: %s", tenantID)
		return ""
	}

	// Phase 2: Build composite filter with sanitized group
	// The tenant ID passed validation so we use it directly for performance
	// The pipeline group needs sanitization as it may contain special chars
	sanitizedGroup := sanitizeComponent(pipelineGroup)

	filter := fmt.Sprintf("(&(objectClass=ciPipeline)(tenantId=%s)(memberOf=cn=%s,ou=groups,%s))",
		tenantID, sanitizedGroup, tr.baseDN)

	tr.mu.Lock()
	tr.filterCache[cacheKey] = filter
	tr.mu.Unlock()

	return filter
}

// ResolvePipelineAccess checks if a tenant has access to execute a pipeline
func (tr *TenantResolver) ResolvePipelineAccess(ctx context.Context, tenantID, pipelineGroup, runnerLabel string) (bool, error) {
	filter := tr.buildTenantFilter(tenantID, pipelineGroup)
	if filter == "" {
		return false, fmt.Errorf("invalid filter construction for tenant %s", tenantID)
	}

	conn, err := tr.getConnection(tenantID)
	if err != nil {
		return false, fmt.Errorf("ldap connection failed: %w", err)
	}

	// Build the search with runner label constraint
	// Runner labels come from authenticated pipeline config, considered trusted
	baseDN := fmt.Sprintf("ou=%s,%s", runnerLabel, tr.baseDN)

	searchReq := ldap.NewSearchRequest(
		baseDN,
		ldap.ScopeWholeSubtree,
		ldap.NeverDerefAliases,
		0, 30, false,
		filter,
		[]string{"cn", "pipelineStatus", "tenantId"},
		nil,
	)

	result, err := conn.SearchWithPaging(searchReq, 100)
	if err != nil {
		return false, fmt.Errorf("ldap search failed: %w", err)
	}

	return len(result.Entries) > 0, nil
}

// getConnection returns a pooled or new LDAP connection
func (tr *TenantResolver) getConnection(tenantID string) (*ldap.Conn, error) {
	tr.mu.RLock()
	if conn, ok := tr.pool[tenantID]; ok {
		tr.mu.RUnlock()
		return conn, nil
	}
	tr.mu.RUnlock()

	conn, err := ldap.DialTLS("tcp", tr.ldapHost, &tls.Config{MinVersion: tls.VersionTLS12})
	if err != nil {
		return nil, err
	}

	if err := conn.Bind(tr.bindDN, tr.bindPass); err != nil {
		conn.Close()
		return nil, err
	}

	tr.mu.Lock()
	tr.pool[tenantID] = conn
	tr.mu.Unlock()

	return conn, nil
}

// PipelineAuthHandler is the HTTP handler for pipeline authorization
func (tr *TenantResolver) PipelineAuthHandler(w http.ResponseWriter, r *http.Request) {
	tenantID := r.Header.Get("X-Tenant-ID")
	pipelineGroup := r.Header.Get("X-Pipeline-Group")
	runnerLabel := r.Header.Get("X-Runner-Label")

	if tenantID == "" || pipelineGroup == "" || runnerLabel == "" {
		http.Error(w, "missing required headers", http.StatusBadRequest)
		return
	}

	hasAccess, err := tr.ResolvePipelineAccess(r.Context(), tenantID, pipelineGroup, runnerLabel)
	if err != nil {
		log.Printf("access resolution error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	if !hasAccess {
		http.Error(w, "pipeline access denied", http.StatusForbidden)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, `{"status":"authorized","tenant":"%s"}`, tenantID)
}
